<script>import {onMount} from 'svelte';import {getUsers} from '../api/usersApi.js';import {getErrorMessage} from '../../../helpers/toolsHelper.js';let users=$state([]);let loading=$state(true);let error=$state('');onMount(async()=>{try{const r=await getUsers();users=Array.isArray(r?.data?.users)?r.data.users:[]}catch(e){error=getErrorMessage(e)}finally{loading=false}});</script><svelte:head><title>Pengguna · Delcom Link Tree</title></svelte:head><p class="eyebrow">ADMINISTRASI</p><h1>Pengguna</h1><p class="muted">Daftar pengguna yang tersedia dari layanan Delcom.</p>{#if loading}<p role="status">Memuat pengguna…</p>{:else if error}<p class="error" role="alert">{error}</p>{:else if !users.length}<div class="empty-state"><h3>Data pengguna kosong</h3><p>Belum ada data pengguna yang dapat ditampilkan.</p></div>{:else}<div class="user-table-wrap"><table><thead><tr><th>Nama</th><th>Email</th><th>ID</th></tr></thead><tbody>{#each users as user (user.id)}<tr><td>{user.name||user.username||'—'}</td><td>{user.email||'—'}</td><td>{user.id}</td></tr>{/each}</tbody></table></div>{/if}
